-- ----------------------------
-- Table structure for fms_closing_template
-- ----------------------------
DROP TABLE IF EXISTS `fms_closing_template`;
CREATE TABLE `fms_closing_template`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `account_set_id` bigint NULL DEFAULT NULL COMMENT '账套编号',
  `preset_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '系统预置编码',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '模板名称',
  `category` int NULL DEFAULT NULL COMMENT '模板分类',
  `period_end` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否期末结转',
  `subject_id` bigint NULL DEFAULT NULL COMMENT '来源科目编号',
  `formula_rule` int NULL DEFAULT NULL COMMENT '取数规则',
  `time_type` int NULL DEFAULT NULL COMMENT '取数时间类型',
  `subject_rules` json NULL COMMENT '结转科目规则数组',
  `sort` int NULL DEFAULT NULL COMMENT '显示顺序',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_account_set_id`(`account_set_id` ASC) USING BTREE,
  INDEX `idx_subject_id`(`subject_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 107 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'FMS 结账模板';

