-- ----------------------------
-- Table structure for fms_closing_voucher
-- ----------------------------
DROP TABLE IF EXISTS `fms_closing_voucher`;
CREATE TABLE `fms_closing_voucher`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `closing_id` bigint NULL DEFAULT NULL COMMENT '结账方案编号',
  `voucher_id` bigint NULL DEFAULT NULL COMMENT '凭证编号',
  `voucher_time` datetime NULL DEFAULT NULL COMMENT '凭证日期',
  `amount` decimal(24, 6) NOT NULL DEFAULT 0.000000 COMMENT '结转金额',
  `closed` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否已结账',
  `account_set_id` bigint NULL DEFAULT NULL COMMENT '账套编号',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
