-- ----------------------------
-- Table structure for fms_finance_parameter
-- ----------------------------
DROP TABLE IF EXISTS `fms_finance_parameter`;
CREATE TABLE `fms_finance_parameter`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `account_set_id` bigint NOT NULL COMMENT '账套编号',
  `level` int NOT NULL COMMENT '科目层级',
  `subject_code_rule` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '科目编码规则',
  `ledger_balance_mode` int NOT NULL COMMENT '账簿余额方向模式',
  `deficit_check` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否检查现金及银行存款科目赤字',
  `voucher_review_required` bit(1) NOT NULL DEFAULT b'1' COMMENT '结账前是否要求凭证审核',
  `asset_period_locked` bit(1) NOT NULL DEFAULT b'0' COMMENT '生成折旧凭证后是否锁定以前期间资产卡片',
  `taxpayer_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '纳税人名称',
  `taxpayer_number` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '纳税人识别号',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_business`(`account_set_id` ASC, `deleted` ASC, `tenant_id` ASC) USING BTREE,
  INDEX `idx_account_set_id`(`account_set_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'FMS 财务参数';

-- ----------------------------
-- Records of fms_finance_parameter
-- ----------------------------
BEGIN;
