-- ----------------------------
-- Table structure for fms_initial_balance
-- ----------------------------
DROP TABLE IF EXISTS `fms_initial_balance`;
CREATE TABLE `fms_initial_balance`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `subject_id` bigint NULL DEFAULT NULL COMMENT '科目编号',
  `auxiliary_accounting` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否启用辅助核算',
  `opening_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '期初金额',
  `opening_quantity` decimal(18, 4) NOT NULL DEFAULT 0.0000 COMMENT '期初数量',
  `year_debit_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '本年累计借方金额',
  `year_debit_quantity` decimal(18, 4) NOT NULL DEFAULT 0.0000 COMMENT '本年累计借方数量',
  `year_credit_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '本年累计贷方金额',
  `year_credit_quantity` decimal(18, 4) NOT NULL DEFAULT 0.0000 COMMENT '本年累计贷方数量',
  `year_opening_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '年初金额',
  `year_opening_quantity` decimal(18, 4) NOT NULL DEFAULT 0.0000 COMMENT '年初数量',
  `profit_loss_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '实际损益发生额',
  `profit_loss_quantity` decimal(18, 4) NOT NULL DEFAULT 0.0000 COMMENT '实际损益发生数量',
  `account_set_id` bigint NULL DEFAULT NULL COMMENT '账套编号',
  `assist_balances` json NULL COMMENT '辅助核算余额数组',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_account_subject`(`account_set_id` ASC, `subject_id` ASC, `deleted` ASC, `tenant_id` ASC) USING BTREE,
  INDEX `idx_subject_id`(`subject_id` ASC) USING BTREE,
  INDEX `idx_account_set_id`(`account_set_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 259 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'FMS 科目期初余额';

