-- ----------------------------
-- Table structure for fms_subject
-- ----------------------------
DROP TABLE IF EXISTS `fms_subject`;
CREATE TABLE `fms_subject`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '科目编码',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '科目名称',
  `parent_id` bigint NOT NULL DEFAULT 0 COMMENT '上级科目',
  `type` int NULL DEFAULT NULL COMMENT '类型',
  `category` int NULL DEFAULT NULL COMMENT '科目类别',
  `balance_direction` int NULL DEFAULT NULL COMMENT '余额方向',
  `quantity_unit` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '数量核算 计量单位',
  `cash` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否现金科目',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态（0开启 1关闭）',
  `level` int NULL DEFAULT NULL COMMENT '层级',
  `quantity_accounting` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否启用数量核算',
  `account_set_id` bigint NULL DEFAULT NULL COMMENT '账套编号',
  `auxiliary_type_ids` json NULL COMMENT '辅助核算类别编号数组',
  `currency_ids` json NULL COMMENT '核算币种编号数组',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_parent_id`(`parent_id` ASC) USING BTREE,
  INDEX `idx_account_set_id`(`account_set_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 853 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'FMS 会计科目';

