-- ----------------------------
-- Table structure for fms_voucher
-- ----------------------------
DROP TABLE IF EXISTS `fms_voucher`;
CREATE TABLE `fms_voucher`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `voucher_word_id` bigint NULL DEFAULT NULL COMMENT '凭证字编号',
  `voucher_number` int NULL DEFAULT NULL COMMENT '凭证号',
  `voucher_time` datetime NULL DEFAULT NULL COMMENT '凭证日期',
  `voucher_period` int GENERATED ALWAYS AS (extract(year_month from `voucher_time`)) STORED COMMENT '凭证期间' NULL,
  `attachment_urls` json NULL COMMENT '附件地址数组',
  `attachment_count` int NOT NULL DEFAULT 0 COMMENT '附件数',
  `debit_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '借方金额',
  `credit_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '贷方金额',
  `total` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '合计金额',
  `status` int NULL DEFAULT NULL COMMENT '状态',
  `reviewer_user_id` bigint NULL DEFAULT NULL COMMENT '审核人后台用户编号',
  `account_set_id` bigint NULL DEFAULT NULL COMMENT '账套编号',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_voucher_word_id`(`voucher_word_id` ASC) USING BTREE,
  INDEX `idx_reviewer_user_id`(`reviewer_user_id` ASC) USING BTREE,
  INDEX `idx_account_set_id`(`account_set_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 86 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'FMS 凭证';

