-- ----------------------------
-- Table structure for fms_voucher_entry
-- ----------------------------
DROP TABLE IF EXISTS `fms_voucher_entry`;
CREATE TABLE `fms_voucher_entry`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `digest` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '摘要内容',
  `subject_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '会计科目内容',
  `quantity` decimal(18, 4) NOT NULL DEFAULT 0.0000 COMMENT '数量',
  `debit_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '借方金额',
  `credit_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '贷方金额',
  `voucher_id` bigint NULL DEFAULT NULL COMMENT '凭证编号',
  `subject_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '科目编码',
  `sort` int NULL DEFAULT NULL COMMENT '显示顺序',
  `subject_id` bigint NULL DEFAULT NULL COMMENT '科目编号',
  `account_set_id` bigint NULL DEFAULT NULL COMMENT '账套编号',
  `unit_price` decimal(18, 6) NOT NULL DEFAULT 0.000000 COMMENT '单价',
  `assist_combination_id` bigint NULL DEFAULT NULL COMMENT '辅助核算组合编号',
  `auxiliaries` json NULL COMMENT '辅助核算项目数组',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_voucher_id`(`voucher_id` ASC) USING BTREE,
  INDEX `idx_subject_id`(`subject_id` ASC) USING BTREE,
  INDEX `idx_account_set_id`(`account_set_id` ASC) USING BTREE,
  INDEX `idx_assist_combination_id`(`assist_combination_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 183 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'FMS 凭证分录';

